\begin{aligned}
    \hat{y} 
    &= \argmax_{y = \{0, 1\}} P(Y = y\mid\mathbf{X} = \mathbf{X}) \\
    &\quad= \argmax_{y = \{0, 1\}}  \frac{P(Y=y)P(\mathbf{X} =\mathbf{x}\mid Y = y)}{P(\mathbf{X} =\mathbf{x})} \\
    &\quad= \argmax_{y = \{0, 1\}} P(Y=y)P(\mathbf{X} =\mathbf{x}\mid Y = y) \quad\text{(since $P(\mathbf{X} =\mathbf{x})$ is constant w.r.t. $Y$)}
\end{aligned}

\begin{aligned}
    \hat{y} 
    &= \argmax\limits_{y = \{0, 1\}} \;P(Y = y)P(\mathbf{X} = \mathbf{x}\mid Y = y) \\ 
    &= \argmax\limits_{y = \{0, 1\}} \; P(Y= y)\prod_i P(X_i = x_i\mid Y = y) \\ 
    &= \argmax\limits_{y = \{0, 1\}} \; \log P(Y = y)  + \sum_i \log P(X_i = x_i\mid Y = y) 
\end{aligned}
